namespace ghidra.framework.plugintool.util;



using ghidra.framework.plugintool;
using ghidra.framework.plugintool;

public class TransientToolState {
	private List<PluginState<object>> states;

	/**
	 * Construct a TransientPluginState
	 * 
	 * @param plugins array of plugins to get transient state for
	 */
	public TransientToolState(List<Plugin> plugins) {
		states = new();
		foreach (Plugin plugin in plugins) {
			if (!(plugin is PluginWithTransientState<object> hasState)) {
				continue;
			}
			PluginState<object> state = PluginState.gather(hasState);
			if (state == null) {
				continue;
			}
			if (state != null) {
				states.add(state);
			}
		}
	}

	/**
	 * Restore the tool's state.
	 */
	public void restoreTool() {
		Iterator<PluginState<object>> it = states.iterator();
		while (it.hasNext()) {
			PluginState<object> ps = it.next();
			ps.restore();
		}
	}

	private static class PluginState<T> {
		private PluginWithTransientState<T> plugin;
		private T state;

		PluginState(PluginWithTransientState<T> plugin, T state) {
			this.plugin = plugin;
			this.state = state;
		}

		static PluginState<T> gather<T>(PluginWithTransientState<T> plugin) {
			T state = plugin.getTransientState();
			if (state == null) {
				return null;
			}
			return new(plugin, state);
		}

		void restore() {
			if (!plugin.isDisposed()) {
				plugin.restoreTransientState(state);
			}
		}
	}
}
